<?php
namespace App\Domain\Testimonials; use App\Models\Testimonial; use Illuminate\Validation\ValidationException; final class TestimonialManager { public function save(array $data,?Testimonial $item,int $userId):Testimonial{$item??=new Testimonial;$data['updated_by']=$userId;if(!$item->exists){$data['created_by']=$userId;$data['status']='draft';$data['display_order']=(int)Testimonial::max('display_order')+1;}else unset($data['status']);$item->fill($data)->save();return $item;} public function publish(Testimonial $item):void{$this->content($item);$item->update(['status'=>'published','published_at'=>now(),'scheduled_for'=>null,'archived_at'=>null]);} public function schedule(Testimonial $item,string $utc):void{$this->content($item);$item->update(['status'=>'scheduled','scheduled_for'=>$utc,'published_at'=>null,'archived_at'=>null]);} public function unpublish(Testimonial $item):void{$item->update(['status'=>'draft','published_at'=>null,'scheduled_for'=>null,'archived_at'=>null]);} public function archive(Testimonial $item):void{if(app(TestimonialDependencyInspector::class)->inspect($item)['blocked'])throw ValidationException::withMessages(['testimonial'=>'Resolve homepage references first.']);$item->update(['status'=>'archived','archived_at'=>now(),'published_at'=>null,'scheduled_for'=>null]);} public function restore(Testimonial $item):void{$item->update(['status'=>'draft','archived_at'=>null,'published_at'=>null,'scheduled_for'=>null]);} public function duplicate(Testimonial $item,int $userId):Testimonial{$copy=$item->replicate(['client_id','status','published_at','scheduled_for','archived_at','created_by','updated_by']);$copy->status='draft';$copy->created_by=$copy->updated_by=$userId;$copy->display_order=(int)Testimonial::max('display_order')+1;$copy->save();return $copy;} public function move(Testimonial $item,string $direction):void{$peer=Testimonial::where('display_order',$direction==='up'?'<':'>',$item->display_order)->orderBy('display_order',$direction==='up'?'desc':'asc')->first();if($peer){$order=$item->display_order;$item->update(['display_order'=>$peer->display_order]);$peer->update(['display_order'=>$order]);}} private function content(Testimonial $item):void{if(!trim($item->person_name)||!trim($item->quote))throw ValidationException::withMessages(['testimonial'=>'A person and genuine quote are required.']);} }
